package servers_test

// L756E (THROWAWAY ab/l756e-diag-20261114, not for merge): the registry columns of the #756 "free Ps x free CPUs" experiment (servers/l756e_arms.go, generated by l756e-gen.py). The
// expectations are stated here, not derived from the code under test; the pin comes from servers/celeris/go.mod.

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

// arm -> the exact column env (every column also carries the sampler).
var l756eWant = map[string]map[string]string{
	"a":   {"PROBATORIUM_SCHED_SAMPLE": "1"},
	"ap":  {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "14", "GOMAXPROCS": "14"},
	"b":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "14", "GOMAXPROCS": "20"},
	"c":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "14", "GOMAXPROCS": "16", "PROBATORIUM_AFFINITY": "0-13"},
	"d":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "16", "GOMAXPROCS": "16"},
	"dp":  {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "16", "GOMAXPROCS": "20"},
	"e":   {"PROBATORIUM_SCHED_SAMPLE": "1", "PROBATORIUM_WORKERS": "12", "GOMAXPROCS": "16"},
	"ctl": {"PROBATORIUM_SCHED_SAMPLE": "1"},
}

var l756eName = regexp.MustCompile(`^l756e-([0-9]{3})-r([1-5])-(a|ap|b|c|d|dp|e|ctl)-(epoll-h1-sync|std-h1)$`)

func l756eColumns(t *testing.T) []servers.Adapter {
	t.Helper()
	var out []servers.Adapter
	for n, a := range servers.Registry {
		if strings.HasPrefix(n, "l756e-") {
			out = append(out, a)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func TestL756EColumns(t *testing.T) {
	cols := l756eColumns(t)
	if len(cols) != 40 {
		t.Fatalf("%d l756e columns, want 40 (5 reps x 7 arms + control)", len(cols))
	}
	mod, err := os.ReadFile(filepath.Join("celeris", "go.mod"))
	if err != nil {
		t.Fatal(err)
	}
	m := regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`).FindSubmatch(mod)
	if m == nil {
		t.Fatal("no celeris require in servers/celeris/go.mod")
	}
	perRep := map[string]map[string]int{}
	baseLoop, baseCtl := servers.Registry["celeris-epoll-h1-sync"], servers.Registry["celeris-std-h1"]
	for i, a := range cols {
		mm := l756eName.FindStringSubmatch(a.Name)
		if mm == nil {
			t.Fatalf("column name %q", a.Name)
		}
		seq, rep, arm, eng := mm[1], mm[2], mm[3], mm[4]
		if want := i + 1; seq != strings.Repeat("0", 3-len(itoa(want)))+itoa(want) {
			t.Errorf("%s: seq %s is not the sorted position %d", a.Name, seq, want)
		}
		if perRep[rep] == nil {
			perRep[rep] = map[string]int{}
		}
		perRep[rep][arm]++
		base := baseLoop
		if arm == "ctl" {
			base = baseCtl
		}
		if (arm == "ctl") != (eng == "std-h1") || a.Engine != eng || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language {
			t.Errorf("%s: engine / capabilities differ from its base column", a.Name)
		}
		if a.Framework != "celeris-l756e-"+arm || a.FrameworkVersion != string(m[1]) {
			t.Errorf("%s: framework %s version %s, want celeris-l756e-%s / %s", a.Name, a.Framework, a.FrameworkVersion, arm, m[1])
		}
		if gb, ok := a.Bin.(servers.GoBinary); !ok || gb.ModuleDir != "servers/celeris" {
			t.Errorf("%s: bin %#v", a.Name, a.Bin)
		}
		want := l756eWant[arm]
		if len(a.SUTEnv) != len(want) {
			t.Errorf("%s: SUTEnv %v, want %v", a.Name, a.SUTEnv, want)
		}
		for k, v := range want {
			if a.SUTEnv[k] != v {
				t.Errorf("%s: SUTEnv[%s] = %q, want %q", a.Name, k, a.SUTEnv[k], v)
			}
		}
		p, ok := a.RatedPlans["ws-large-echo"]
		if !ok || len(a.RatedPlans) != 1 || len(p.Fractions) != 0 || len(p.AbsoluteRPS) != 2 || p.AbsoluteRPS[0] != 16753 || p.AbsoluteRPS[1] != 25129 || p.Placeholder || p.SaturationOnly {
			t.Errorf("%s: rated plans %#v, want exactly ws-large-echo: no fractions, absolute 16753 and 25129", a.Name, a.RatedPlans)
		}
		if a.Baseline {
			t.Errorf("%s: Baseline is set", a.Name)
		}
	}
	for rep, arms := range perRep {
		if len(arms) != 8 {
			t.Errorf("rep %s has %d arms, want 8", rep, len(arms))
		}
		for arm, n := range arms {
			if n != 1 {
				t.Errorf("rep %s arm %s %d times", rep, arm, n)
			}
		}
	}
	if len(perRep) != 5 {
		t.Errorf("%d reps, want 5", len(perRep))
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for ; n > 0; n /= 10 {
		b = append([]byte{byte('0' + n%10)}, b...)
	}
	return string(b)
}
